[
  {
    "statement": "Based on the available evidence, long-term fishery closures show more positive effects on marine fish abundance compared to temporary closures.",
    "citations": [
      "2655",
      "2664",
      "2098"
    ]
  },
  {
    "statement": "Long-term closures lasting 6-8 years demonstrated higher abundance in 2 of 7 fish species in the Gulf of Maine and Bismark Sea.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "Temporary closures showed no increase in fish biomass or abundance for cod in the Atlantic Ocean over nine years.",
    "citations": [
      "2664"
    ]
  },
  {
    "statement": "Temporary closures showed no increase in invertebrate biomass at sites seasonally closed to fishing in the English Channel.",
    "citations": [
      "2098"
    ]
  },
  {
    "statement": "Both temporary and long-term closures showed mixed or neutral results for some species.",
    "citations": [
      "2664",
      "2655"
    ]
  },
  {
    "statement": "Temporary closures had no effect on cod survival or condition.",
    "citations": [
      "2664"
    ]
  },
  {
    "statement": "Long-term closures showed either similar or lower abundance for certain species like monkfish and salmon.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "The evidence suggests that longer protection periods may be necessary to see measurable increases in fish abundance.",
    "citations": []
  },
  {
    "statement": "Responses of fish abundance to fishery closures vary by species.",
    "citations": []
  }
]

[
  {
    "statement": "Marine Protected Areas (MPAs) with complete fishing prohibitions have demonstrated significant positive effects on fish abundance and diversity.",
    "citations": []
  },
  {
    "statement": "A systematic review of 79 studies found that 30 of 54 site comparison studies reported higher abundances of fish species in MPAs with fishing prohibitions compared to fished areas.",
    "citations": []
  },
  {
    "statement": "The positive effects on fish abundance within Marine Protected Areas with fishing prohibitions were observed up to 25 years or more after implementation.",
    "citations": []
  },
  {
    "statement": "The positive effects of fishing prohibitions were consistently found for both fishery-targeted and non-targeted species.",
    "citations": []
  },
  {
    "statement": "14 of 20 site comparison studies found higher fish species richness and diversity in Marine Protected Areas with fishing prohibitions compared to fished areas.",
    "citations": []
  },
  {
    "statement": "Studies revealed that fish in no-fishing Marine Protected Areas were larger overall.",
    "citations": []
  },
  {
    "statement": "8 of 11 site comparison studies reported larger fish sizes for most species groups monitored in no-fishing Marine Protected Areas.",
    "citations": []
  },
  {
    "statement": "Some variation in responses to fishing prohibitions was observed between different fish species and groups.",
    "citations": []
  },
  {
    "statement": "The effects of fishing prohibitions sometimes depended on factors such as a fish's position in the food chain, commercial target status, and size.",
    "citations": []
  },
  {
    "statement": "Marine Protected Areas with limited fishing exceptions showed more variable results.",
    "citations": []
  },
  {
    "statement": "Some studies found that Marine Protected Areas with limited fishing exceptions had similar fish biomass and density compared to fished areas.",
    "citations": []
  }
]

[
  {
    "statement": "Several gear modifications are available to reduce unwanted catch of cod and haddock in the North Sea.",
    "citations": []
  },
  {
    "statement": "Separator trawls separate unwanted cod from target fish species into the lower codend.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "A larger mesh size in the lower codend of a separator trawl allows more unwanted smaller cod to escape capture.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "Topless trawls reduced the catch of unwanted Atlantic cod and discards of commercial fish species compared to conventional trawl types.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Topless trawls reduced unwanted catches of larger haddock, but not smaller haddock.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Fitting size-sorting escape grids to trawl nets reduced catches of unwanted cod and haddock compared to trawls without grids.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Results were mixed on whether fitting size-sorting escape grids improved size-selection for cod and haddock specifically.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Fitting mesh escape panels to trawl nets reduced unwanted catches of various fish species, including cod and haddock.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "Some studies found no reduction in unwanted catches for cod and haddock when using mesh escape panels compared to nets without the panels.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "Different designs or configurations of size-sorting escape grid systems in trawl nets had varying effects on reducing unwanted catches.",
    "citations": [
      "2728"
    ]
  },
  {
    "statement": "Some escape grid configurations are more effective than others depending on the specific circumstances.",
    "citations": [
      "2728"
    ]
  },
  {
    "statement": "The effectiveness of gear modifications to reduce unwanted catch varies depending on factors such as species, fish size, gear configuration, and fishing conditions.",
    "citations": []
  }
]

[
  {
    "statement": "Mesh escape panels, size-sorting grids, and large supported openings all show effectiveness in improving size-selectivity in trawl nets.",
    "citations": []
  },
  {
    "statement": "The performance of mesh escape panels, size-sorting grids, and large supported openings varies by species and configuration.",
    "citations": []
  },
  {
    "statement": "Mesh escape panels demonstrated improved size selectivity for species like Atlantic cod and haddock.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "The results from using mesh escape panels varied with the panel's position and design.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "Size-sorting escape grids were effective at reducing unwanted catch of various species including cod, haddock, and whiting.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Size-sorting escape grids resulted in improved size-selection for haddock.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "The performance of size-sorting escape grids varied by species.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Large supported openings were effective at reducing unwanted catch of species like red snapper and other fish.",
    "citations": [
      "2723"
    ]
  },
  {
    "statement": "Specific size-selectivity improvements for large supported openings were not as prominently featured in the evidence.",
    "citations": [
      "2723"
    ]
  },
  {
    "statement": "When used in combination, grids and large openings together were effective at reducing unwanted catch.",
    "citations": [
      "2726"
    ]
  },
  {
    "statement": "The evidence suggests that mesh escape panels have the broadest evidence base for size-selectivity improvements.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "Grids show strong performance for unwanted catch reduction.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Large supported openings are effective but have more limited evidence for size-selectivity specifically.",
    "citations": [
      "2723"
    ]
  }
]

[
  {
    "statement": "There is limited but specific evidence from available studies on the comparative effects of prohibiting static fishing gear versus prohibiting line fishing on fish abundance.",
    "citations": []
  },
  {
    "statement": "A study in the Coral Sea found that areas closed to non-towed fishing gears had higher overall shark abundance when sampled with longlines compared to areas where commercial gillnets were permitted.",
    "citations": []
  },
  {
    "statement": "In the Coral Sea study, shark length was greater for two of five species or groups in areas closed to non-towed fishing gears.",
    "citations": []
  },
  {
    "statement": "A study in the Indian Ocean found that prohibiting offshore line fishing and all other boat-based fishing resulted in higher abundances of four fish species that were over-exploited by line fishing.",
    "citations": []
  },
  {
    "statement": "The higher abundances of four over-exploited fish species were found when compared to areas where boat-based line and spear fishing was permitted.",
    "citations": []
  },
  {
    "statement": "Evidence suggests both prohibiting static fishing gear and prohibiting line fishing can have positive effects on fish abundance.",
    "citations": []
  },
  {
    "statement": "The prohibition of static gear appears beneficial for shark populations.",
    "citations": []
  },
  {
    "statement": "The prohibition of line fishing helps recover species specifically over-exploited by line fishing.",
    "citations": []
  }
]

[
  {
    "statement": "Marine protected areas with zonation systems that permit some fishing show mixed outcomes for fish populations.",
    "citations": []
  },
  {
    "statement": "Zones with higher protection levels, such as no-take or no-entry zones, generally had greater fish abundance compared to partially fished zones within the same protected area.",
    "citations": []
  },
  {
    "statement": "Zones with higher protection levels, such as no-take or no-entry zones, generally had greater fish biomass compared to partially fished zones within the same protected area.",
    "citations": []
  },
  {
    "statement": "Zones with higher protection levels, such as no-take or no-entry zones, generally had greater species richness compared to partially fished zones within the same protected area.",
    "citations": []
  },
  {
    "statement": "Site comparison studies across multiple regions found that fish abundance and biomass varied with the level of fishing restriction.",
    "citations": []
  },
  {
    "statement": "No-fishing zones had higher fish abundance and biomass values than partially fished zones.",
    "citations": []
  },
  {
    "statement": "Fish sizes were larger in zones with greater protection restrictions.",
    "citations": []
  },
  {
    "statement": "One study found fish abundance increased in no-entry zones compared to no-take and fished zones.",
    "citations": []
  },
  {
    "statement": "The effects of zonation on fish populations varied between fish feeding groups, zone protection level, and reef region.",
    "citations": []
  },
  {
    "statement": "Fish behavior showed positive responses in high-protection zones.",
    "citations": []
  },
  {
    "statement": "Tagged reef fish remained mainly in zones where all or nearly all fishing was prohibited for up to 20 years.",
    "citations": []
  }
]

[
  {
    "statement": "The effectiveness of prohibiting mobile bottom fishing gears varies across different regions.",
    "citations": []
  },
  {
    "statement": "In the North Atlantic Ocean, research shows mixed effectiveness of prohibiting mobile bottom fishing gears.",
    "citations": []
  },
  {
    "statement": "After 14 years of closure to bottom trawling in a North Atlantic study area, the recruitment of young red mullet had increased.",
    "citations": []
  },
  {
    "statement": "Closing an area in the North Atlantic to bottom trawling did not increase the recruitment or survival of young haddock seven years after the closure when compared to trawled areas.",
    "citations": []
  },
  {
    "statement": "Studies in the Mediterranean Sea show generally positive results from prohibiting mobile bottom fishing gears.",
    "citations": []
  },
  {
    "statement": "In the Mediterranean, adult red mullet showed increased biomass and larger sizes after a 14-year closure to bottom trawling.",
    "citations": []
  },
  {
    "statement": "After the closure of an area in the Mediterranean to bottom trawling, recruitment of young red mullet had increased.",
    "citations": []
  },
  {
    "statement": "The increased recruitment of young fish following a bottom trawling closure in the Mediterranean was not consistent across all fish groups.",
    "citations": []
  },
  {
    "statement": "Research from the Indian Ocean region shows that the results of prohibiting mobile bottom fishing gears vary depending on habitat type and individual fish groups.",
    "citations": []
  },
  {
    "statement": "In the Indian Ocean region, studies found that closing areas to towed bottom gears for 3-14 years had effects on fish size that varied between individual fish groups and with habitat type.",
    "citations": []
  },
  {
    "statement": "The effectiveness of prohibitions on bottom fishing gear appears to be highly variable across regions.",
    "citations": []
  },
  {
    "statement": "The effectiveness of bottom fishing gear prohibitions is influenced by the duration of the closure, which ranged from 3 to 15 years in the studies.",
    "citations": []
  },
  {
    "statement": "The effectiveness of bottom fishing gear prohibitions is influenced by habitat type.",
    "citations": []
  },
  {
    "statement": "The effectiveness of bottom fishing gear prohibitions is influenced by the specific fish species or groups studied.",
    "citations": []
  }
]

[
  {
    "statement": "Both separator trawls and topless trawls have shown effectiveness at reducing unwanted fish catch.",
    "citations": []
  },
  {
    "statement": "Separator trawls and topless trawls work through different mechanisms.",
    "citations": []
  },
  {
    "statement": "Separator trawls and topless trawls have been studied to varying extents.",
    "citations": []
  },
  {
    "statement": "A study in the North Sea found separator trawls separated unwanted cod from target species into a lower codend with larger mesh sizes.",
    "citations": []
  },
  {
    "statement": "The larger mesh sizes in the separator trawls' lower codend allowed more smaller cod to escape.",
    "citations": []
  },
  {
    "statement": "A study in the Atlantic Ocean found separator trawls caught less of one of two unwanted fish species when fitted with square-mesh escape panels.",
    "citations": []
  },
  {
    "statement": "Topless trawls were studied more extensively, with four studies conducted across the North Sea, Gulf of Maine, and Baltic Sea regions.",
    "citations": []
  },
  {
    "statement": "Studies on topless trawls showed mixed but generally positive results.",
    "citations": []
  },
  {
    "statement": "Two studies found that topless trawls reduced unwanted Atlantic cod catch and discards of commercial species.",
    "citations": []
  },
  {
    "statement": "One study found that topless trawls reduced catches of larger haddock but not smaller haddock.",
    "citations": []
  },
  {
    "statement": "One study found that topless trawls reduced catches of larger cod in only one case.",
    "citations": []
  },
  {
    "statement": "Another study found that using topless trawls reduced discarded catches for one of four commercial species.",
    "citations": []
  },
  {
    "statement": "Evidence suggests both separator trawls and topless trawls can be effective for bycatch reduction.",
    "citations": []
  },
  {
    "statement": "Topless trawls have more extensive supporting research than separator trawls.",
    "citations": []
  }
]

[
  {
    "statement": "The documented effects of modifying fishing trap or pot configurations on marine fish are based on 23 studies.",
    "citations": []
  },
  {
    "statement": "Sixteen of 20 replicated studies found that modifications to trap configuration reduced unwanted catches of various fish species.",
    "citations": []
  },
  {
    "statement": "Modifications to trap configurations included using different trap types, increased mesh size, and fitting escape devices.",
    "citations": []
  },
  {
    "statement": "Unwanted catches are defined as undersized, discarded, or non-commercial catches.",
    "citations": []
  },
  {
    "statement": "Fish species with reduced unwanted catches included brown trout, black sea bass, herring, bluethroat wrasse, leatherjacket, cod, protected rockfishes, whitefish, American eel, winter flounder, sharks/rays, salmon, and rainbow trout.",
    "citations": []
  },
  {
    "statement": "One study also found lower numbers of unwanted species, both fish and invertebrates, in modified traps.",
    "citations": []
  },
  {
    "statement": "Three studies found no effect on unwanted catches of white croaker, non-commercial fish, or undersized Atlantic cod.",
    "citations": []
  },
  {
    "statement": "One study noted increased non-target haddock catches.",
    "citations": []
  },
  {
    "statement": "One replicated, controlled study found similar survival rates between small herring that escaped through size-sorting grids and trap-caught herring that did not pass through grids.",
    "citations": []
  },
  {
    "statement": "Three of four replicated studies found that traps modified with square mesh escape windows or larger mesh sizes improved size-selectivity for Atlantic cod, black sea bass, and most fish species compared to smaller mesh and/or standard gear.",
    "citations": []
  },
  {
    "statement": "One study found no effect of trap modifications on panga size-selectivity.",
    "citations": []
  }
]

[
  {
    "statement": "Based on nine studies examining electropositive deterrents on fishing gear, the evidence shows mixed results for reducing unwanted catches of sharks and rays.",
    "citations": []
  },
  {
    "statement": "Two of four replicated, controlled studies found that fishing gear fitted with electropositive deterrent materials caught fewer unwanted spiny dogfish, longnose skate, sharks and rays compared to standard fishing gear.",
    "citations": []
  },
  {
    "statement": "Two of four replicated, controlled studies also found that fishing gear fitted with electropositive deterrent materials caught fewer undersized halibut compared to standard fishing gear.",
    "citations": []
  },
  {
    "statement": "Two other studies and a global systematic review found that electropositive deterrents resulted in similar catches of unwanted spiny dogfish compared to gear with no deterrents.",
    "citations": []
  },
  {
    "statement": "Two other studies and a global systematic review found that electropositive deterrents resulted in similar total catches of sharks, blue sharks, and sharks and rays compared to gear with no deterrents.",
    "citations": []
  },
  {
    "statement": "Behavioural studies showed that three of four studies found reduced feeding attempts by spiny dogfish, great hammerhead, and draughtboard sharks when deterrent materials were present.",
    "citations": []
  },
  {
    "statement": "Behavioural studies showed that three of four studies found reduced bait consumption by spiny dogfish, great hammerhead, and draughtboard sharks when deterrent materials were present.",
    "citations": []
  },
  {
    "statement": "One behavioural study found that deterrent materials had no effect on bonnethead and young lemon sharks.",
    "citations": []
  }
]

[
  {
    "statement": "Evidence from European waters shows that square mesh codends are generally more effective than diamond mesh codends for reducing unwanted catch in trawl nets.",
    "citations": []
  },
  {
    "statement": "In the English Channel, square mesh codends reduced non-commercial unwanted invertebrates in one of two areas compared to diamond mesh codends.",
    "citations": []
  },
  {
    "statement": "When combined with square mesh escape panels, square mesh codends caught fewer unwanted non-commercial invertebrates compared to standard trawl nets.",
    "citations": []
  },
  {
    "statement": "When combined with square mesh escape panels, square mesh codends reduced numbers of discarded finfish compared to standard trawl nets.",
    "citations": []
  },
  {
    "statement": "Some studies showed that square mesh codends reduced unwanted catches of all fish species monitored.",
    "citations": []
  },
  {
    "statement": "Square mesh codends reduced unwanted catches of young individuals of half or most commercially targeted fish.",
    "citations": []
  },
  {
    "statement": "Square mesh codends reduced the total unwanted catch of fish and invertebrates.",
    "citations": []
  },
  {
    "statement": "Square mesh codends reduced discarded fish in deeper waters.",
    "citations": []
  },
  {
    "statement": "Studies found that square mesh codends improved size selectivity for various species compared to diamond mesh codends.",
    "citations": []
  },
  {
    "statement": "Square mesh codends improved size selectivity for species including European hake, axillary seabream, poor cod, greater forkbeard, blue whiting, and discarded fish compared to diamond mesh codends.",
    "citations": []
  }
]

[
  {
    "statement": "Fourteen of twenty site comparison studies found higher fish species richness in marine protected areas compared to fished areas.",
    "citations": []
  },
  {
    "statement": "The protection periods in the studies finding higher fish species richness ranged from 1 to over 25 years.",
    "citations": []
  },
  {
    "statement": "Seven studies found a different fish community composition in no-fishing zones after 3 to 16 years.",
    "citations": []
  },
  {
    "statement": "Thirty of fifty-four studies found higher fish abundances and biomass in marine protected areas where fishing is prohibited.",
    "citations": []
  },
  {
    "statement": "Multiple studies demonstrated larger fish sizes in protected areas.",
    "citations": []
  },
  {
    "statement": "Some studies found similar species richness between protected and fished areas.",
    "citations": []
  },
  {
    "statement": "Some studies found similar community composition between protected and fished areas.",
    "citations": []
  },
  {
    "statement": "The responses of fish communities to protection in a marine area are variable.",
    "citations": []
  },
  {
    "statement": "The variability in responses of fish communities to protection depends on the species, the location, and the duration of the protection.",
    "citations": []
  }
]

[
  {
    "statement": "Both square mesh codends and rotated diamond mesh codends show different effectiveness patterns for improving size-selectivity in trawl nets.",
    "citations": []
  },
  {
    "statement": "26 studies have examined square mesh codends.",
    "citations": []
  },
  {
    "statement": "6 studies have examined rotated diamond mesh codends.",
    "citations": []
  },
  {
    "statement": "Square mesh codends demonstrated improved size selectivity in 6 of 14 studies.",
    "citations": []
  },
  {
    "statement": "Square mesh codends showed benefits for species like silver hake, horse mackerel, European hake, and roundfish species.",
    "citations": []
  },
  {
    "statement": "5 studies found no difference in size selectivity between square mesh and diamond mesh for species like Atlantic mackerel and flatfish.",
    "citations": []
  },
  {
    "statement": "The effectiveness of square mesh codends varied with fish body shape.",
    "citations": []
  },
  {
    "statement": "The use of square mesh codends generally improved selectivity for roundfish but not for flatfish.",
    "citations": []
  },
  {
    "statement": "Rotated diamond mesh with a 90° orientation showed improved size selectivity in 4 of 6 studies.",
    "citations": []
  },
  {
    "statement": "Rotated diamond mesh improved size selectivity for cod, red mullet, common pandora, and round-bodied species.",
    "citations": []
  },
  {
    "statement": "Rotated diamond mesh showed no improvement in size selectivity for plaice, annular sea bream, and flatfish.",
    "citations": []
  },
  {
    "statement": "One study found no improvement in size selectivity for cod, plaice, and flounder with rotated mesh.",
    "citations": []
  },
  {
    "statement": "Both square mesh codends and rotated diamond mesh codends showed improved selectivity for round-bodied fish.",
    "citations": []
  },
  {
    "statement": "Both square mesh codends and rotated diamond mesh codends showed limited effectiveness for flatfish species.",
    "citations": []
  },
  {
    "statement": "Square mesh codends have been more extensively studied across global fisheries.",
    "citations": []
  },
  {
    "statement": "Research on rotated diamond mesh has been conducted primarily in European waters.",
    "citations": []
  },
  {
    "statement": "Rotated diamond mesh research has occurred in the Baltic Sea, Kattegat, Skagerrak, Aegean Sea, and North Sea.",
    "citations": []
  }
]

[
  {
    "statement": "Research shows clear differences in how prohibiting all commercial fishing affects fish community composition between the Tasman Sea and South Atlantic Ocean.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the Tasman Sea, studies found that fish assemblage and species composition was different before and after prohibiting all commercial fishing.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "One study in a Tasman Sea estuary showed changes in fish composition after two years of prohibiting commercial fishing.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "Another study in the Tasman Sea region surrounding two marine reserves found different species composition five years after the creation of the reserves.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "A study in the South Atlantic Ocean found no change in species composition between a reserve closed to all commercial fishing for 40 years and unprotected fished areas.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "A South Atlantic study found no difference in overall fish diversity between a 40-year protected area and fished areas.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "Research from other regions showed varying results for fish diversity.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "Tasman Sea studies produced mixed findings regarding fish abundance.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "One Tasman Sea study found most fish species had lower abundance two years after a fishing closure compared to before the closure.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "Another Tasman Sea study found fish abundance varied over time with some groups having higher abundance than others.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the South Atlantic, research showed higher abundances of one of four commercially targeted fish species in a 40-year protected area compared to fished areas.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "A study in the South Atlantic found mixed effects on fish densities, with the effects varying with the level of commercial exploitation.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "A study in the South Atlantic found higher abundances of all five commercially exploited species that were examined.",
    "citations": [
      "2667"
    ]
  }
]

[
  {
    "statement": "Evidence from global systematic reviews shows that catch share systems have demonstrated effectiveness for sustainable fish stock management.",
    "citations": []
  },
  {
    "statement": "Two worldwide systematic reviews found that catch share fisheries had lower rates of over-exploitation compared to non-catch share fisheries.",
    "citations": []
  },
  {
    "statement": "A higher proportion of fisheries using catch shares met or exceeded management target levels for exploitation rates.",
    "citations": []
  },
  {
    "statement": "One systematic review found that fisheries managed under catch shares were more likely to meet management target levels for biomass sustainability.",
    "citations": []
  },
  {
    "statement": "Another systematic review found no difference in biomass-based management target performance between catch shares, fleet-wide catch caps, and fishing effort controls.",
    "citations": []
  },
  {
    "statement": "Evidence specifically evaluating catch shares by area is lacking.",
    "citations": []
  },
  {
    "statement": "One study that examined species-specific catch shares showed that Individual Vessel Bycatch Quota systems reduced unwanted halibut catch compared to Individual Transferable Quota systems.",
    "citations": []
  },
  {
    "statement": "The evidence base on catch share systems primarily comes from systematic reviews covering global fisheries.",
    "citations": []
  },
  {
    "statement": "There are limited specific studies on particular catch share design variations.",
    "citations": []
  }
]

[
  {
    "statement": "Temporary and long-term fishery closures show different effects on marine fish populations.",
    "citations": []
  },
  {
    "statement": "Temporary closures showed mixed results for marine fish populations.",
    "citations": [
      "2664"
    ]
  },
